from pwn import remote
import time

HOST = 'misc.chal.csaw.io'
PORT = 3001

inputs = [
    'x+y=0',
    '1.0000 -1.0000',
    '1.0000*x+1.0000*y+0.0000=0',
    'boundary',
    'equation',
    '',
]

def try_input(userin):
    r = remote(HOST, PORT)
    try:
        data = r.recv(timeout=2)
    except:
        data = b''
    if userin != '':
        r.sendline(userin.encode())
    else:
        r.sendline(b'')
    try:
        out = r.recvall(timeout=2)
    except:
        out = b''
    r.close()
    return data.decode(errors='replace'), out.decode(errors='replace')

def main():
    results = []
    for userin in inputs:
        before, after = try_input(userin)
        results.append({'input': userin, 'prompt': before, 'reply': after})
    for r in results:
        print('--------')
        print(f"Input: {repr(r['input'])}")
        print(f"Prompt: {r['prompt']}")
        print(f"Reply: {r['reply']}")

if __name__ == '__main__':
    main()

from pwn import remote
import time

HOST = 'misc.chal.csaw.io'
PORT = 3001

xs = [
    -1.10, -1.09, -1.08, -1.07, -1.06, -1.05, -1.04, -1.03, -1.02, -1.01, -1.00
]
y = -3.0000

results = {}
for x in xs:
    try:
        conn = remote(HOST, PORT, timeout=8)
        recv = b''
        while not b'Enter x:' in recv:
            chunk = conn.recv(1, timeout=2)
            if not chunk:
                break
            recv += chunk
        conn.sendline(f'{x:.4f}'.encode())
        recv = b''
        while not b'Enter y:' in recv:
            chunk = conn.recv(1, timeout=2)
            if not chunk:
                break
            recv += chunk
        conn.sendline(f'{y:.4f}'.encode())
        resp = b''
        t0 = time.time()
        # Read until we see the expected response
        while time.time() - t0 < 8:
            chunk = conn.recv(1, timeout=2)
            if not chunk:
                break
            resp += chunk
            if b'Cool numbers!' in resp or b'Not cool numbers!' in resp:
                break
        output = resp.decode(errors='ignore').strip()
        conn.close()
    except Exception as e:
        output = f'Error: {e}'
    results[x] = output

print('x value | Server response')
print('-'*30)
for x in xs:
    print(f'{x:.2f}   | {results[x]}')

def find_flip(results):
    last = None
    for x in xs:
        curr = results[x]
        if last and curr != last:
            print(f'Flip detected between {x-0.01:.2f} -> {x:.2f}')
        last = curr

find_flip(results)

